    43	static bool allocate_document_id(uint64_t *out_id)
    44	{
    45	    uint64_t current = atomic_load_explicit(&next_document_id, memory_order_relaxed);
    46	    for (;;) {
    47	        if (current == 0U || current == UINT64_MAX) return false;
    48	        if (atomic_compare_exchange_weak_explicit(&next_document_id, &current,
    49	                current + 1U, memory_order_relaxed, memory_order_relaxed)) {
    50	            *out_id = current;
    51	            return true;
    52	        }
    53	    }
    54	}
