    64	static document_model_error create_nodes(document_model *model, const svg_xml_token *tokens,
    65	                                         size_t token_count, size_t element_count,
    66	                                         size_t attribute_count)
    67	{
    68	    if (element_count == 0U || element_count > DOCUMENT_MODEL_MAX_NODES ||
    69	        element_count > UINT32_MAX || element_count > SIZE_MAX / sizeof(*model->nodes))
    70	        return DOCUMENT_MODEL_LIMIT;
    71	    model->nodes = calloc(element_count, sizeof(*model->nodes));
    72	    if (model->nodes == NULL) return DOCUMENT_MODEL_OUT_OF_MEMORY;
    73	    model->node_count = element_count;
    74	    model->live_node_count = element_count;
    75	    if (attribute_count > 0U) {
    76	        if (attribute_count > SIZE_MAX / sizeof(*model->attributes)) return DOCUMENT_MODEL_LIMIT;
    77	        model->attributes = calloc(attribute_count, sizeof(*model->attributes));
    78	        if (model->attributes == NULL) return DOCUMENT_MODEL_OUT_OF_MEMORY;
    79	    }
    80	    model->attribute_count = attribute_count;
    81	    uint32_t stack[DOCUMENT_MODEL_MAX_DEPTH];
    82	    size_t depth = 0U;
    83	    size_t next_slot = 0U;
    84	    size_t next_attribute = 0U;
    85	    for (size_t i = 0U; i < token_count; ++i) {
    86	        const svg_xml_token *token = &tokens[i];
    87	        if (token->kind == SVG_XML_TOKEN_END_ELEMENT) {
    88	            if (depth == 0U) return DOCUMENT_MODEL_PARSE;
    89	            document_node *node = &model->nodes[stack[depth - 1U]];
    90	            if (node->source.offset > token->source.offset) return DOCUMENT_MODEL_PARSE;
    91	            size_t end = token->source.offset + token->source.length;
    92	            if (end < token->source.offset || end > model->source.len) return DOCUMENT_MODEL_PARSE;
    93	            node->source.length = end - node->source.offset;
    94	            --depth;
    95	        } else if (token->kind == SVG_XML_TOKEN_START_ELEMENT ||
    96	                   token->kind == SVG_XML_TOKEN_EMPTY_ELEMENT) {
    97	            if (next_slot >= element_count || token->name.offset > model->source.len ||
    98	                token->name.length > model->source.len - token->name.offset ||
    99	                token->source.offset > model->source.len ||
   100	                token->source.length > model->source.len - token->source.offset)
   101	                return DOCUMENT_MODEL_PARSE;
   102	            document_node *node = &model->nodes[next_slot];
   103	            node->name = token->name;
   104	            node->source.offset = token->source.offset;
   105	            node->source.length = token->source.length;
   106	            node->parent = depth == 0U ? UINT32_MAX : stack[depth - 1U];
   107	            node->depth = depth;
   108	            node->first_attribute = next_attribute;
   109	            while (i + 1U < token_count && tokens[i + 1U].kind == SVG_XML_TOKEN_ATTRIBUTE) {
   110	                const svg_xml_token *attribute = &tokens[++i];
   111	                if (next_attribute >= attribute_count ||
   112	                    attribute->name.offset > model->source.len ||
   113	                    attribute->name.length > model->source.len - attribute->name.offset ||
   114	                    attribute->value.offset > model->source.len ||
   115	                    attribute->value.length > model->source.len - attribute->value.offset)
   116	                    return DOCUMENT_MODEL_PARSE;
   117	                model->attributes[next_attribute].name = attribute->name;
   118	                model->attributes[next_attribute].value = attribute->value;
   119	                ++next_attribute;
   120	                ++node->attribute_count;
   121	            }
   122	            node->first_child = UINT32_MAX;
   123	            node->last_child = UINT32_MAX;
   124	            node->next_sibling = UINT32_MAX;
   125	            node->generation = 1U;
   126	            node->live = true;
   127	            if (depth == 0U) model->root = (uint32_t)next_slot;
   128	            else append_child(model, node->parent, (uint32_t)next_slot);
   129	            if (token->kind == SVG_XML_TOKEN_START_ELEMENT) {
   130	                if (depth >= DOCUMENT_MODEL_MAX_DEPTH) return DOCUMENT_MODEL_LIMIT;
   131	                stack[depth++] = (uint32_t)next_slot;
   132	            }
   133	            ++next_slot;
   134	        }
   135	    }
   136	    return next_slot == element_count && next_attribute == attribute_count && depth == 0U ?
   137	        DOCUMENT_MODEL_OK : DOCUMENT_MODEL_PARSE;
   138	}
