   140	document_model_result document_model_parse(base_bytes source)
   141	{
   142	    document_model_result result = {0};
   143	    result.error = DOCUMENT_MODEL_INVALID_ARGUMENT;
   144	    if (!base_bytes_valid(source)) return result;
   145	    svg_xml_options options = svg_xml_default_options();
   146	    if (source.len > options.limits.input_bytes) {
   147	        result.error = DOCUMENT_MODEL_LIMIT;
   148	        result.parse_diagnostic.category = SVG_XML_ERROR_INPUT_LIMIT;
   149	        return result;
   150	    }
   151	    svg_xml_token_stream *stream = NULL;
   152	    svg_xml_stream_status status = svg_xml_token_stream_start(source,
   153	        DOCUMENT_MODEL_MAX_TOKEN_BYTES, NULL, NULL, &stream);
   154	    if (status != SVG_XML_STREAM_OK) {
   155	        result.error = DOCUMENT_MODEL_OUT_OF_MEMORY;
   156	        return result;
   157	    }
   158	    do { status = svg_xml_token_stream_step(stream, 64U * 1024U); }
   159	    while (status == SVG_XML_STREAM_OK);
   160	    svg_xml_result parsed = svg_xml_token_stream_result(stream);
   161	    result.parse_diagnostic = parsed.diagnostic;
   162	    if (status != SVG_XML_STREAM_COMPLETE || parsed.diagnostic.category != SVG_XML_ERROR_NONE) {
   163	        if (status == SVG_XML_STREAM_FAILED &&
   164	            parsed.diagnostic.category == SVG_XML_ERROR_OUTPUT_EXHAUSTED) {
   165	            /* The shared tokenizer uses one code for its storage cap and realloc failure. */
   166	            result.error = DOCUMENT_MODEL_RESOURCE_EXHAUSTED;
   167	        } else result.error = DOCUMENT_MODEL_PARSE;
   168	        svg_xml_token_stream_destroy(stream);
   169	        return result;
   170	    }
   171	    svg_xml_token *tokens = NULL;
   172	    size_t token_count = 0U;
   173	    bool taken = svg_xml_token_stream_take(stream, &tokens, &token_count);
   174	    svg_xml_token_stream_destroy(stream);
   175	    if (!taken) {
   176	        result.error = DOCUMENT_MODEL_PARSE;
   177	        return result;
   178	    }
   179	    document_model *model = calloc(1U, sizeof(*model));
   180	    if (model == NULL) {
   181	        free(tokens);
   182	        result.error = DOCUMENT_MODEL_OUT_OF_MEMORY;
   183	        return result;
   184	    }
   185	    model->source = source;
   186	    model->root = UINT32_MAX;
   187	    bool id_ok = allocate_document_id(&model->id);
   188	    document_model_error nodes_error = id_ok ? create_nodes(model, tokens, token_count,
   189	        parsed.element_count, parsed.attribute_count) : DOCUMENT_MODEL_ID_EXHAUSTED;
   190	    free(tokens);
   191	    if (nodes_error != DOCUMENT_MODEL_OK) {
   192	        free(model->nodes);
   193	        free(model->attributes);
   194	        free(model);
   195	        result.error = nodes_error;
   196	        return result;
   197	    }
   198	    result.error = DOCUMENT_MODEL_OK;
   199	    result.model = model;
   200	    return result;
   201	}
