   222	static const document_node *resolve(const document_model *model, document_handle handle)
   223	{
   224	    if (model == NULL || handle.document_id != model->id ||
   225	        handle.slot >= model->node_count) return NULL;
   226	    document_node *node = &model->nodes[handle.slot];
   227	    return node->live && node->generation == handle.generation ? node : NULL;
   228	}
