   248	    if (node == NULL || out == NULL) return false;
   249	    uint32_t child = node->first_child;
   250	    while (child != UINT32_MAX && !model->nodes[child].live)
   251	        child = model->nodes[child].next_sibling;
   252	    if (child == UINT32_MAX) return false;
   253	    *out = make_handle(model, child);
