   339	bool document_model_remove_subtree(document_model *model, document_handle handle)
   340	{
   341	    if (resolve(model, handle) == NULL) return false;
   342	    for (size_t i = 0U; i < model->node_count; ++i) {
   343	        uint32_t parent = (uint32_t)i;
   344	        bool descendant = false;
   345	        while (parent != UINT32_MAX) {
   346	            if (parent == handle.slot) { descendant = true; break; }
   347	            parent = model->nodes[parent].parent;
   348	        }
   349	        if (!descendant) continue;
   350	        document_node *entry = &model->nodes[i];
   351	        if (entry->live) {
   352	            entry->live = false;
   353	            --model->live_node_count;
   354	            if (entry->generation != UINT32_MAX) ++entry->generation;
   355	        }
   356	    }
   357	    if (handle.slot == model->root) model->root = UINT32_MAX;
   358	    return true;
   359	}
