    20	static bool token_storage_limit_case(void)
    21	{
    22	    const size_t token_limit = (64U * 1024U * 1024U) / sizeof(svg_xml_token);
    23	    if (token_limit >= 1000000U) return false;
    24	    size_t children = token_limit;
    25	    size_t child_bytes = 0U, total_bytes = 0U;
    26	    if (!base_size_mul(children, 4U, &child_bytes) ||
    27	        !base_size_add(5U, child_bytes, &total_bytes) ||
    28	        !base_size_add(total_bytes, 6U, &total_bytes)) return false;
    29	    uint8_t *source = malloc(total_bytes);
    30	    if (source == NULL) return false;
    31	    size_t offset = 0U;
    32	    memcpy(source + offset, "<svg>", 5U); offset += 5U;
    33	    for (size_t i = 0U; i < children; ++i) {
    34	        memcpy(source + offset, "<a/>", 4U); offset += 4U;
    35	    }
    36	    memcpy(source + offset, "</svg>", 6U); offset += 6U;
    37	    document_model_result result = document_model_parse((base_bytes){source, offset});
    38	    bool passed = result.model == NULL &&
    39	        result.error == DOCUMENT_MODEL_RESOURCE_EXHAUSTED &&
    40	        result.parse_diagnostic.category == SVG_XML_ERROR_OUTPUT_EXHAUSTED;
    41	    document_model_destroy(result.model);
    42	    free(source);
    43	    return passed;
    44	}
