 45	pub(crate) fn parse_document_with_storage(source: &[u8], storage_limit: usize) -> Result<DocumentModel<'_>, DocumentParseError> {
 46	    if storage_limit < size_of::<XmlToken>() {
 47	        return Err(DocumentParseError { error: DocumentError::ResourceExhausted, diagnostic: XmlDiagnostic::default() });
 48	    }
 49	    if source.len() > vexel_xml::MAX_INPUT_BYTES {
 50	        return Err(DocumentParseError {
 51	            error: DocumentError::Limit,
 52	            diagnostic: XmlDiagnostic { category: XmlError::InputLimit, offset: vexel_xml::MAX_INPUT_BYTES },
 53	        });
 54	    }
 55	
 56	    let mut stream = XmlTokenStream::new(source, storage_limit).map_err(|_| DocumentParseError {
 57	        error: DocumentError::OutOfMemory,
 58	        diagnostic: XmlDiagnostic::default(),
 59	    })?;
 60	    if stream.token_storage_bytes() > storage_limit
 61	        || stream.open_name_storage_bytes() > MAX_OPEN_NAME_BYTES
 62	    {
 63	        return Err(DocumentParseError { error: DocumentError::OutOfMemory, diagnostic: XmlDiagnostic::default() });
 64	    }
 65	    let status = loop {
 66	        let status = stream.step(STEP_BYTES, false);
 67	        if stream.token_storage_bytes() > storage_limit
 68	            || stream.open_name_storage_bytes() > MAX_OPEN_NAME_BYTES
 69	        {
 70	            return Err(DocumentParseError { error: DocumentError::OutOfMemory, diagnostic: stream.result().diagnostic });
 71	        }
 72	        if status != StreamStatus::Ok { break status; }
 73	    };
 74	    let result = stream.result();
 75	    if status != StreamStatus::Complete || result.diagnostic.category != XmlError::None {
 76	        let error = match result.diagnostic.category {
 77	            XmlError::InputLimit | XmlError::NodeLimit | XmlError::DepthLimit | XmlError::AttributeLimit
 78	            | XmlError::TextLimit => DocumentError::Limit,
 79	            XmlError::OutputExhausted => DocumentError::ResourceExhausted,
 80	            XmlError::None => DocumentError::OutOfMemory,
 81	            _ => DocumentError::Parse,
 82	        };
 83	        return Err(DocumentParseError { error, diagnostic: result.diagnostic });
 84	    }
 85	
 86	    if result.element_count == 0 || result.element_count > MAX_NODES || result.element_count > u32::MAX as usize
 87	        || result.attribute_count > vexel_xml::MAX_TOTAL_ATTRIBUTES
 88	        || checked_table_bytes::<Node>(result.element_count).is_none()
 89	        || checked_table_bytes::<Attribute>(result.attribute_count).is_none()
 90	    {
 91	        return Err(DocumentParseError { error: DocumentError::Limit, diagnostic: result.diagnostic });
 92	    }
 93	    let tokens = stream.take().ok_or(DocumentParseError {
 94	        error: DocumentError::Parse,
 95	        diagnostic: result.diagnostic,
 96	    })?;
 97	    if stream.token_storage_bytes() != 0 {
 98	        return Err(DocumentParseError { error: DocumentError::Parse, diagnostic: result.diagnostic });
 99	    }
100	
101	    let id = allocate_document_id().ok_or(DocumentParseError {
102	        error: DocumentError::IdExhausted,
103	        diagnostic: result.diagnostic,
104	    })?;
105	    let (nodes, attributes, root) = build_tables(source, &tokens, result.element_count, result.attribute_count)
106	        .map_err(|error| DocumentParseError { error, diagnostic: result.diagnostic })?;
107	    Ok(DocumentModel::from_parts(source, id, nodes, attributes, Some(root)))
108	}
109	
110	fn build_tables(
111	    source: &[u8],
112	    tokens: &[XmlToken],
113	    node_count: usize,
114	    attribute_count: usize,
115	) -> Result<(Vec<Node>, Vec<Attribute>, u32), DocumentError> {
116	    let mut nodes: Vec<Node> = Vec::new();
117	    nodes.try_reserve_exact(node_count).map_err(|_| DocumentError::OutOfMemory)?;
118	    if nodes.capacity() > MAX_NODES { return Err(DocumentError::OutOfMemory); }
119	    let mut attributes: Vec<Attribute> = Vec::new();
120	    attributes.try_reserve_exact(attribute_count).map_err(|_| DocumentError::OutOfMemory)?;
121	    if attributes.capacity() > vexel_xml::MAX_TOTAL_ATTRIBUTES { return Err(DocumentError::OutOfMemory); }
122	    let mut stack: Vec<u32> = Vec::new();
123	    stack.try_reserve_exact(MAX_DEPTH).map_err(|_| DocumentError::OutOfMemory)?;
124	    if stack.capacity() > MAX_DEPTH { return Err(DocumentError::OutOfMemory); }
125	
126	    let mut root = None;
127	    let mut index = 0usize;
128	    while index < tokens.len() {
129	        let token = tokens[index];
130	        match token.kind {
131	            TokenKind::StartElement | TokenKind::EmptyElement => {
132	                if nodes.len() >= node_count || nodes.len() >= MAX_NODES || nodes.len() >= u32::MAX as usize
133	                    || token.name.slice(source).is_none() || checked_span(token.source, source).is_none()
134	                {
135	                    return Err(DocumentError::Parse);
136	                }
137	                let slot = u32::try_from(nodes.len()).map_err(|_| DocumentError::Limit)?;
138	                let parent = stack.last().copied().unwrap_or(no_slot());
139	                let depth = stack.len();
140	                let mut node = Node {
141	                    name: token.name,
142	                    source: DocumentSourceSpan { offset: token.source.offset, length: token.source.length },
143	                    first_attribute: attributes.len(),
144	                    depth,
145	                    parent,
146	                    ..Node::default()
147	                };
148	                if parent != no_slot() {
149	                    let parent_index = parent as usize;
150	                    let parent_node = nodes.get(parent_index).ok_or(DocumentError::Parse)?;
151	                    let previous_last = parent_node.last_child;
152	                    if parent_node.first_child == no_slot() { nodes[parent_index].first_child = slot; }
153	                    else {
154	                        let previous = nodes.get_mut(previous_last as usize).ok_or(DocumentError::Parse)?;
155	                        previous.next_sibling = slot;
156	                    }
157	                    nodes[parent_index].last_child = slot;
158	                } else if parent == no_slot() {
159	                    if root.replace(slot).is_some() { return Err(DocumentError::Parse); }
160	                } else {
161	                    return Err(DocumentError::Parse);
162	                }
163	
164	                index += 1;
165	                while let Some(attribute) = tokens.get(index).filter(|next| next.kind == TokenKind::Attribute) {
166	                    if attributes.len() >= attribute_count || attribute.name.slice(source).is_none()
167	                        || attribute.value.slice(source).is_none() || checked_span(attribute.source, source).is_none()
168	                    {
169	                        return Err(DocumentError::Parse);
170	                    }
171	                    attributes.push(Attribute { name: attribute.name, value: attribute.value });
172	                    node.attribute_count += 1;
173	                    index += 1;
174	                }
175	                nodes.push(node);
176	                if token.kind == TokenKind::StartElement {
177	                    if stack.len() >= MAX_DEPTH { return Err(DocumentError::Limit); }
178	                    stack.push(slot);
179	                }
180	            }
181	            TokenKind::EndElement => {
182	                let Some(slot) = stack.pop() else { return Err(DocumentError::Parse); };
183	                let node = nodes.get_mut(slot as usize).ok_or(DocumentError::Parse)?;
184	                let end = token.source.offset.checked_add(token.source.length).ok_or(DocumentError::Parse)?;
185	                let node_end = node.source.offset.checked_add(node.source.length).ok_or(DocumentError::Parse)?;
186	                if node.source.offset > token.source.offset || end < node_end || end > source.len()
187	                    || token.name.slice(source).is_none()
188	                {
189	                    return Err(DocumentError::Parse);
190	                }
191	                node.source.length = end.checked_sub(node.source.offset).ok_or(DocumentError::Parse)?;
192	                index += 1;
193	            }
194	            _ => index += 1,
195	        }
196	    }
197	    if !stack.is_empty() || nodes.len() != node_count || attributes.len() != attribute_count {
198	        return Err(DocumentError::Parse);
199	    }
200	    Ok((nodes, attributes, root.ok_or(DocumentError::Parse)?))
201	}
202	
203	fn checked_span<'a>(span: XmlSpan, source: &'a [u8]) -> Option<&'a [u8]> {
204	    let end = span.offset.checked_add(span.length)?;
205	    source.get(span.offset..end)
206	}
