 46	/// An immutable-source document with safely owned indexes and mutable live
 47	/// state. The source borrow must outlive this model.
 48	#[derive(Debug)]
 49	pub struct DocumentModel<'source> {
 50	    pub(crate) source: &'source [u8],
 51	    pub(crate) id: u64,
 52	    pub(crate) nodes: Vec<Node>,
 53	    pub(crate) attributes: Vec<Attribute>,
 54	    pub(crate) live_node_count: usize,
 55	    pub(crate) root: Option<u32>,
 56	}
 57	
 58	impl<'source> DocumentModel<'source> {
 59	    pub(crate) fn from_parts(
 60	        source: &'source [u8],
 61	        id: u64,
 62	        nodes: Vec<Node>,
 63	        attributes: Vec<Attribute>,
 64	        root: Option<u32>,
 65	    ) -> Self {
 66	        let live_node_count = nodes.len();
 67	        Self { source, id, nodes, attributes, live_node_count, root }
 68	    }
 69	
 70	    pub fn document_id(&self) -> u64 { self.id }
 71	    pub fn source(&self) -> &'source [u8] { self.source }
 72	    pub fn node_count(&self) -> usize { self.nodes.len() }
 73	    pub fn live_node_count(&self) -> usize { self.live_node_count }
 74	
 75	    pub fn root(&self) -> Option<DocumentHandle> {
 76	        let slot = self.root?;
 77	        self.nodes.get(slot as usize).filter(|node| node.live)?;
 78	        Some(self.handle(slot))
 79	    }
 80	
 81	    pub fn first_child(&self, parent: DocumentHandle) -> Option<DocumentHandle> {
 82	        let node = self.resolve(parent)?;
 83	        let mut child = node.first_child;
 84	        while child != NO_SLOT {
 85	            let current = self.nodes.get(child as usize)?;
 86	            if current.live { return Some(self.handle(child)); }
 87	            child = current.next_sibling;
 88	        }
 89	        None
 90	    }
 91	
 92	    pub fn next_sibling(&self, handle: DocumentHandle) -> Option<DocumentHandle> {
 93	        let node = self.resolve(handle)?;
 94	        let mut sibling = node.next_sibling;
 95	        while sibling != NO_SLOT {
 96	            let current = self.nodes.get(sibling as usize)?;
 97	            if current.live { return Some(self.handle(sibling)); }
 98	            sibling = current.next_sibling;
 99	        }
100	        None
101	    }
102	
103	    pub fn parent(&self, handle: DocumentHandle) -> Option<DocumentHandle> {
104	        let node = self.resolve(handle)?;
105	        if node.parent == NO_SLOT { return None; }
106	        self.nodes.get(node.parent as usize).filter(|parent| parent.live)?;
107	        Some(self.handle(node.parent))
108	    }
109	
110	    pub fn tag_name(&self, handle: DocumentHandle) -> Option<&'source [u8]> {
111	        self.resolve(handle)?.name.slice(self.source)
112	    }
113	
114	    pub fn attribute_count(&self, handle: DocumentHandle) -> usize {
115	        self.resolve(handle).map_or(0, |node| node.attribute_count)
116	    }
117	
118	    pub fn attribute_at(&self, handle: DocumentHandle, index: usize) -> Option<(&'source [u8], &'source [u8])> {
119	        let node = self.resolve(handle)?;
120	        if index >= node.attribute_count { return None; }
121	        let attribute = self.attributes.get(node.first_attribute.checked_add(index)?)?;
122	        Some((attribute.name.slice(self.source)?, attribute.value.slice(self.source)?))
123	    }
124	
125	    pub fn depth(&self, handle: DocumentHandle) -> Option<usize> {
126	        Some(self.resolve(handle)?.depth)
127	    }
128	
129	    pub fn node_at(&self, slot: usize) -> Option<DocumentHandle> {
130	        let index = u32::try_from(slot).ok()?;
131	        self.nodes.get(slot).filter(|node| node.live)?;
132	        Some(self.handle(index))
133	    }
134	
135	    pub fn source_span(&self, handle: DocumentHandle) -> Option<DocumentSourceSpan> {
136	        Some(self.resolve(handle)?.source)
137	    }
138	
139	    /// Removes a node and all descendants. Slots remain stable; each live
140	    /// generation advances so previously issued handles cannot resolve.
141	    pub fn remove_subtree(&mut self, handle: DocumentHandle) -> bool {
142	        if self.resolve(handle).is_none() { return false; }
143	        for index in 0..self.nodes.len() {
144	            if !self.is_descendant_or_self(index, handle.slot as usize) { continue; }
145	            let node = &mut self.nodes[index];
146	            if node.live {
147	                node.live = false;
148	                self.live_node_count -= 1;
149	                if node.generation != u32::MAX { node.generation += 1; }
150	            }
151	        }
152	        if self.root == Some(handle.slot) { self.root = None; }
153	        true
154	    }
155	
156	    fn is_descendant_or_self(&self, index: usize, ancestor: usize) -> bool {
157	        let mut current = index;
158	        loop {
159	            if current == ancestor { return true; }
160	            let Some(node) = self.nodes.get(current) else { return false; };
161	            if node.parent == NO_SLOT { return false; }
162	            current = node.parent as usize;
163	        }
164	    }
