166	    fn resolve(&self, handle: DocumentHandle) -> Option<&Node> {
167	        if handle.document_id != self.id { return None; }
168	        let node = self.nodes.get(handle.slot as usize)?;
169	        (node.live && node.generation == handle.generation).then_some(node)
170	    }
