 53	const ENTITIES: [&[u8]; 5]=[b"lt",b"gt",b"amp",b"apos",b"quot"];
 54	#[derive(Clone, Copy)]
 55	struct NameClass { xml_exact: bool, xml_folded: bool, entities: u8 }
 56	impl NameClass {
 57	    fn new()->Self{Self{xml_exact:true,xml_folded:true,entities:31}}
 58	    fn push(&mut self,cp:u32,offset:usize){
 59	        self.xml_exact&=b"xml".get(offset).is_some_and(|v|u32::from(*v)==cp);
 60	        self.xml_folded&=cp<128&&b"xml".get(offset).is_some_and(|v|*v==(cp as u8).to_ascii_lowercase());
 61	        for (i,name) in ENTITIES.iter().enumerate(){
 62	            if !name.get(offset).is_some_and(|v|u32::from(*v)==cp){self.entities&=!(1<<i)}
 63	        }
 64	    }
 65	    fn known_entity(self,len:usize)->bool{ENTITIES.iter().enumerate().any(|(i,n)|self.entities&(1<<i)!=0&&n.len()==len)}
