 68	#[derive(Clone, Copy)]
 69	struct NameCompare { left:XmlSpan, right:XmlSpan, index:usize, left_byte:Option<u8> }
 70	#[derive(PartialEq, Eq)]
 71	enum CompareStatus { Pending, Equal, Different, Canceled }
 72	impl NameCompare {
 73	    fn new(left:XmlSpan,right:XmlSpan)->Self{Self{left,right,index:0,left_byte:None}}
 74	    fn step<C:FnMut()->bool>(&mut self,source:&[u8],work:&mut NameWork,cancel:&mut C)->CompareStatus{
 75	        if self.left.length!=self.right.length{return CompareStatus::Different}
 76	        while self.index<self.left.length{
 77	            if work.remaining==0{return CompareStatus::Pending}
 78	            if cancel(){return CompareStatus::Canceled}
 79	            if self.left_byte.is_none(){
 80	                self.left_byte=work.load(source,self.left.offset+self.index,true);
 81	                continue
 82	            }
 83	            let Some(right)=work.load(source,self.right.offset+self.index,true)else{return CompareStatus::Pending};
 84	            if self.left_byte.take()!=Some(right){return CompareStatus::Different}
 85	            self.index+=1;
 86	        }
 87	        CompareStatus::Equal
 88	    }
 89	}
