143	impl<'a> XmlTokenStream<'a> {
144	    pub fn new(source:&'a [u8],max_storage_bytes:usize)->Result<Self,StreamStatus>{
145	        if max_storage_bytes<size_of::<XmlToken>(){return Err(StreamStatus::Failed)}
146	        Self::construct(source,max_storage_bytes,false)
147	    }
148	    pub fn new_visitor(source:&'a [u8])->Result<Self,StreamStatus>{
149	        let scratch=MAX_ATTRIBUTES_PER_ELEMENT.checked_add(1).and_then(|n|n.checked_mul(size_of::<XmlToken>())).ok_or(StreamStatus::Failed)?;
150	        Self::construct(source,scratch,true)
151	    }
152	    fn construct(source:&'a [u8],max_storage_bytes:usize,visitor_mode:bool)->Result<Self,StreamStatus>{
153	        if source.len()>MAX_LARGE_INPUT_BYTES{return Err(StreamStatus::Failed)}
154	        let limits=XmlLimits{input_bytes:MAX_LARGE_INPUT_BYTES,..XmlLimits::default()};
155	        let mut tag_scratch=Vec::new();
156	        if visitor_mode {
157	            let scratch_capacity=MAX_ATTRIBUTES_PER_ELEMENT.checked_add(1).ok_or(StreamStatus::Failed)?;
158	            if tag_scratch.try_reserve_exact(scratch_capacity).is_err()
159	                || tag_scratch.capacity()>scratch_capacity || tag_scratch.capacity()<scratch_capacity {
160	                return Err(StreamStatus::Failed)
161	            }
162	        }
163	        let mut open_names=Vec::new();
164	        if open_names.try_reserve_exact(MAX_DEPTH).is_err()
165	            || open_names.capacity()>MAX_DEPTH || open_names.capacity()<MAX_DEPTH {
166	            return Err(StreamStatus::Failed)
167	        }
168	        let cursor=if source.starts_with(b"\xef\xbb\xbf"){3}else{0};
169	        Ok(Self{source,limits,result:XmlResult::default(),tokens:Vec::new(),tag_scratch,token_capacity:max_storage_bytes/size_of::<XmlToken>(),visitor_mode,
170	            cursor,parse_limit:cursor,char_cursor:0,utf8:Utf8Scan::default(),name_work:NameWork::default(),chars_complete:false,depth:0,roots:0,total_attrs:0,open_names,
171	            pending:Pending::None,tag:None,doctype_seen:false,complete:false,canceled:false,failed:false,taken:false})
172	    }
