174	    pub(crate) fn with_limits(source:&'a [u8],limits:XmlLimits,token_capacity:usize)->Result<Self,StreamStatus>{
175	        let mut stream=Self::construct(source,0,false)?;
176	        stream.limits=limits;
177	        stream.token_capacity=token_capacity.min((isize::MAX as usize)/size_of::<XmlToken>());
