181	    pub fn step(&mut self,budget:usize,canceled:bool)->StreamStatus{
182	        let mut poll=||canceled;
183	        self.step_inner(budget,&mut poll,None)
184	    }
185	    pub fn step_with_visitor<F:FnMut(&XmlToken)->bool>(&mut self,budget:usize,canceled:bool,visitor:&mut F)->StreamStatus{
186	        let mut poll=||canceled;
187	        self.step_inner(budget,&mut poll,Some(visitor))
188	    }
189	    pub fn step_with_visitor_and_cancel<F:FnMut(&XmlToken)->bool,C:FnMut()->bool>(&mut self,budget:usize,visitor:&mut F,cancel:&mut C)->StreamStatus{
190	        self.step_inner(budget,cancel,Some(visitor))
191	    }
192	    pub fn step_with_cancel<C:FnMut()->bool>(&mut self,budget:usize,cancel:&mut C)->StreamStatus{
193	        self.step_inner(budget,cancel,None)
194	    }
195	    fn step_inner<C:FnMut()->bool>(&mut self,budget:usize,cancel:&mut C,mut visitor:Option<&mut dyn FnMut(&XmlToken)->bool>)->StreamStatus{
196	        let status=self.advance_step(budget,cancel,&mut visitor);
197	        if matches!(status,StreamStatus::Failed|StreamStatus::Canceled){
198	            self.failed|=status==StreamStatus::Failed;
199	            self.tokens.clear();self.tag_scratch.clear();
200	            self.result.token_count=0;self.result.element_count=0;
201	            self.result.attribute_count=0;self.result.node_count=0;
202	        }
203	        status
204	    }
205	    fn advance_step<C:FnMut()->bool>(&mut self,budget:usize,cancel:&mut C,visitor:&mut Option<&mut dyn FnMut(&XmlToken)->bool>)->StreamStatus{
206	        if self.failed{return StreamStatus::Failed}
207	        if self.canceled{return StreamStatus::Canceled} if self.result.diagnostic.category!=XmlError::None{return StreamStatus::Failed}
208	        if budget==0{return StreamStatus::Failed} if self.complete{return StreamStatus::Complete}
209	        if self.visitor_mode&&visitor.is_none(){return StreamStatus::Failed}
210	        if cancel(){self.canceled=true;return StreamStatus::Canceled}
211	        let budget=budget.min(STEP_CAP);let char_initial=self.char_cursor;
212	        if !self.scan_chars(budget,cancel){return self.failed_or_canceled()}
213	        if !self.chars_complete{return StreamStatus::Ok}
214	        let char_work=self.char_cursor.saturating_sub(char_initial);if char_work>=budget{return StreamStatus::Ok}
215	        let parse_budget=budget-char_work;self.name_work.begin(parse_budget);let initial=self.frontier();
216	        let limit=initial.saturating_add(parse_budget).min(self.source.len());self.parse_limit=limit;
217	        while self.cursor<self.source.len()&&self.frontier().saturating_sub(initial)<parse_budget {
218	            if cancel(){self.canceled=true;return StreamStatus::Canceled}
219	            let before=self.frontier();let work_before=self.name_work.spent;
220	            if !self.parse_next(limit,visitor,cancel){return self.failed_or_canceled()}
221	            if self.name_work.remaining==0||(self.frontier()==before&&self.name_work.spent==work_before){break}
222	        }
223	        if self.cursor==self.source.len()&&matches!(self.pending,Pending::None)&&self.tag.is_none(){
224	            if self.depth!=0||self.roots==0{self.fail(XmlError::IncompleteDocument,self.source.len());return self.failed_or_canceled()}
225	            self.complete=true;
226	        }
227	        if self.complete{StreamStatus::Complete}else{StreamStatus::Ok}
228	    }
229	    fn scan_chars<C:FnMut()->bool>(&mut self,budget:usize,cancel:&mut C)->bool{
230	        let end=self.char_cursor.saturating_add(budget).min(self.source.len());
231	        while self.char_cursor<end{
232	            if cancel(){self.canceled=true;return false}
233	            let at=self.char_cursor;
234	            match self.utf8.push(self.source[at],at){
235	                Err(start)=>{self.fail(XmlError::InvalidUtf8,start);return false},
236	                Ok(Some(cp)) if !is_xml_char(cp)=>{self.fail(XmlError::InvalidCharacter,self.utf8.start);return false},
237	                Ok(_)=>self.char_cursor+=1,
238	            }
239	        }
240	        if self.char_cursor==self.source.len(){
241	            if self.utf8.incomplete(){self.fail(XmlError::InvalidUtf8,self.utf8.start);return false}
242	            self.chars_complete=true
243	        }
244	        true
245	    }
246	    fn parse_next<C:FnMut()->bool>(&mut self,limit:usize,visitor:&mut Option<&mut dyn FnMut(&XmlToken)->bool>,cancel:&mut C)->bool{
247	        if self.tag.is_some(){return self.parse_tag(limit,visitor,cancel)}
248	        if !matches!(self.pending,Pending::None){return self.parse_pending(limit,visitor,cancel)}
249	        let p=self.cursor;if p>=limit{return true}
250	        if self.source[p]!=b'<'{self.pending=Pending::Text{start:p,pos:p,nonspace:false,first_nonspace:0,reference:None};return self.parse_pending(limit,visitor,cancel)}
251	        if self.source.get(p..p.saturating_add(4))==Some(b"<!--"){self.pending=Pending::Comment{start:p,pos:p+4,dashes:0};return self.parse_pending(limit,visitor,cancel)}
252	        if self.source.get(p..p.saturating_add(9))==Some(b"<![CDATA["){self.pending=Pending::Cdata{start:p,pos:p+9,brackets:0};return self.parse_pending(limit,visitor,cancel)}
253	        if self.source.get(p..p.saturating_add(9))==Some(b"<!DOCTYPE"){
254	            if self.depth!=0||self.roots!=0||self.doctype_seen{self.fail(XmlError::MalformedSyntax,p);return false}
255	            self.pending=Pending::Doctype{start:p,pos:p+9,state:Dtd::default()};return self.parse_pending(limit,visitor,cancel)
256	        }
257	        if self.source.get(p..p.saturating_add(8))==Some(b"<!ENTITY"){self.fail(XmlError::UnsupportedDtd,p);return false}
258	        if self.source.get(p..p.saturating_add(2))==Some(b"<?"){self.pending=Pending::Pi{start:p,pos:p+2,name_scan:None,name:None,declaration:false,data:None,separating:false,question:false};return self.parse_pending(limit,visitor,cancel)}
259	        if self.source.get(p..p.saturating_add(2))==Some(b"</"){self.tag=Some(TagState::new(p,true));return self.parse_tag(limit,visitor,cancel)}
260	        if self.source.get(p..p.saturating_add(2))==Some(b"<!"){self.fail(XmlError::MalformedSyntax,p);return false}
261	        self.tag=Some(TagState::new(p,false));self.parse_tag(limit,visitor,cancel)
262	    }
263	    fn parse_pending<C:FnMut()->bool>(&mut self,limit:usize,visitor:&mut Option<&mut dyn FnMut(&XmlToken)->bool>,cancel:&mut C)->bool{
264	        let pending=core::mem::replace(&mut self.pending,Pending::None);
265	        match pending{
266	            Pending::None=>true,
267	            Pending::Text{start,mut pos,mut nonspace,mut first_nonspace,mut reference}=>{
268	                while pos<limit&&pos<self.source.len(){if cancel(){self.pending=Pending::Text{start,pos,nonspace,first_nonspace,reference};self.canceled=true;return false}
269	                    if self.source[pos]==b'<'{break}
270	                    if self.source.get(pos..pos+3)==Some(b"]]>"){self.fail(XmlError::MalformedSyntax,pos);return false}
271	                    if self.source[pos]==b'&'{if !nonspace{nonspace=true;first_nonspace=pos}let scan=reference.get_or_insert_with(||RefScan::new(pos));match reference_step(self.source,scan,limit,&mut self.name_work){Ok(Some(end))=>{pos=end;reference=None},Ok(None)=>break,Err((e,at))=>{self.fail(e,at);return false}}}
272	                    else{if !is_xml_whitespace(self.source[pos])&&!nonspace{nonspace=true;first_nonspace=pos}pos+=1}
273	                }
274	                if pos<self.source.len()&&self.source[pos]==b'<'{return self.finish_text(start,pos,nonspace,first_nonspace,visitor)}
275	                if pos==self.source.len(){return self.finish_text(start,pos,nonspace,first_nonspace,visitor)}
276	                self.pending=Pending::Text{start,pos,nonspace,first_nonspace,reference};true
277	            }
278	            Pending::Comment{start,mut pos,mut dashes}=>{
279	                while pos<limit&&pos<self.source.len(){if cancel(){self.pending=Pending::Comment{start,pos,dashes};self.canceled=true;return false}
280	                    let c=self.source[pos];if dashes==2{if c!=b'>'{self.fail(XmlError::MalformedSyntax,pos-2);return false}let end=pos+1;let t=XmlToken{kind:TokenKind::Comment,source:span(start,end),value:span(start+4,pos-2),depth:self.depth,..XmlToken::default()};if !self.count_node(start){return false}if !self.emit(t,start,visitor){return false}self.cursor=end;return true}
281	                    dashes=if c==b'-'{dashes+1}else{0};pos+=1;
282	                }
283	                if pos==self.source.len(){self.fail(XmlError::MalformedSyntax,start);return false}self.pending=Pending::Comment{start,pos,dashes};true
284	            }
285	            Pending::Cdata{start,mut pos,mut brackets}=>{
286	                while pos<limit&&pos<self.source.len(){if cancel(){self.pending=Pending::Cdata{start,pos,brackets};self.canceled=true;return false}
287	                    let c=self.source[pos];if c==b'>'&&brackets>=2{if self.depth==0{self.fail(XmlError::MalformedSyntax,start);return false}
288	                        if pos-2-(start+9)>self.limits.text_run_bytes{self.fail(XmlError::TextLimit,start+9);return false}let end=pos+1;let t=XmlToken{kind:TokenKind::Cdata,source:span(start,end),value:span(start+9,pos-2),depth:self.depth,..XmlToken::default()};if !self.count_node(start){return false}if !self.emit(t,start,visitor){return false}self.cursor=end;return true}brackets=if c==b']'{(brackets+1).min(2)}else{0};pos+=1;
289	                }
290	                if pos==self.source.len(){self.fail(XmlError::MalformedSyntax,start);return false}self.pending=Pending::Cdata{start,pos,brackets};true
291	            }
292	            Pending::Doctype{start,mut pos,mut state}=>{
293	                while pos<limit&&pos<self.source.len(){if cancel(){self.pending=Pending::Doctype{start,pos,state};self.canceled=true;return false}
294	                    match state.step(self.source[pos]){Ok(done)=>{pos+=1;if done{let t=XmlToken{kind:TokenKind::Doctype,source:span(start,pos),depth:self.depth,..XmlToken::default()};if !self.count_node(start){return false}self.doctype_seen=true;if !self.emit(t,start,visitor){return false}self.cursor=pos;return true}},Err(())=>{self.fail(XmlError::MalformedSyntax,pos);return false}}
