 16	/// XML 1.0 Fifth Edition `Char` production.
 17	pub const fn is_xml_char(cp: u32) -> bool {
 18	    cp == 0x9
 19	        || cp == 0xa
 20	        || cp == 0xd
 21	        || (cp >= 0x20 && cp <= 0xd7ff)
 22	        || (cp >= 0xe000 && cp <= 0xfffd)
 23	        || (cp >= 0x10000 && cp <= 0x10ffff)
 24	}
