 26	/// Decodes one strict UTF-8 scalar at `position` and returns it with the next
 27	/// byte offset. On failure, callers retain their original position.
 28	pub fn utf8_next(bytes: &[u8], position: usize) -> Option<(u32, usize)> {
 29	    let first = *bytes.get(position)?;
 30	    let (count, mut value) = match first {
 31	        0x00..=0x7f => (1usize, u32::from(first)),
 32	        0xc2..=0xdf => (2, u32::from(first & 0x1f)),
 33	        0xe0..=0xef => (3, u32::from(first & 0x0f)),
 34	        0xf0..=0xf4 => (4, u32::from(first & 0x07)),
 35	        _ => return None,
 36	    };
 37	    let end = position.checked_add(count)?;
 38	    let tail = bytes.get(position + 1..end)?;
 39	    for &byte in tail {
 40	        if byte & 0xc0 != 0x80 {
 41	            return None;
 42	        }
 43	        value = (value << 6) | u32::from(byte & 0x3f);
 44	    }
 45	    let second = *tail.first().unwrap_or(&0);
 46	    if (count == 3 && ((first == 0xe0 && second < 0xa0) || (first == 0xed && second >= 0xa0)))
 47	        || (count == 4 && ((first == 0xf0 && second < 0x90) || (first == 0xf4 && second >= 0x90)))
 48	        || value > 0x10ffff
 49	        || (0xd800..=0xdfff).contains(&value)
 50	    {
 51	        return None;
 52	    }
 53	    Some((value, end))
 54	}
