 56	/// XML 1.0 Fifth Edition `NameStartChar` production.
 57	pub const fn is_name_start(cp: u32) -> bool {
 58	    cp == 0x3a
 59	        || cp == 0x5f
 60	        || (cp >= 0x41 && cp <= 0x5a)
 61	        || (cp >= 0x61 && cp <= 0x7a)
 62	        || (cp >= 0xc0 && cp <= 0xd6)
 63	        || (cp >= 0xd8 && cp <= 0xf6)
 64	        || (cp >= 0xf8 && cp <= 0x2ff)
 65	        || (cp >= 0x370 && cp <= 0x37d)
 66	        || (cp >= 0x37f && cp <= 0x1fff)
 67	        || (cp >= 0x200c && cp <= 0x200d)
 68	        || (cp >= 0x2070 && cp <= 0x218f)
 69	        || (cp >= 0x2c00 && cp <= 0x2fef)
 70	        || (cp >= 0x3001 && cp <= 0xd7ff)
 71	        || (cp >= 0xf900 && cp <= 0xfdcf)
 72	        || (cp >= 0xfdf0 && cp <= 0xfffd)
 73	        || (cp >= 0x10000 && cp <= 0xeffff)
 74	}
 75	
 76	/// XML 1.0 Fifth Edition `NameChar` production.
 77	pub const fn is_name_char(cp: u32) -> bool {
 78	    is_name_start(cp)
 79	        || cp == 0x2d
 80	        || cp == 0x2e
 81	        || (cp >= 0x30 && cp <= 0x39)
 82	        || cp == 0xb7
 83	        || (cp >= 0x300 && cp <= 0x36f)
 84	        || (cp >= 0x203f && cp <= 0x2040)
 85	}
