145	#[derive(Debug, Clone, Copy)]
146	struct DoctypeState {
147	    phase: DoctypePhase,
148	    quote: u8,
149	    run: u8,
150	    subset_closed: bool,
151	}
152	
153	impl Default for DoctypeState {
154	    fn default() -> Self {
155	        Self { phase: DoctypePhase::Start, quote: 0, run: 0, subset_closed: false }
156	    }
157	}
158	
159	impl DoctypeState {
160	    fn step(&mut self, byte: u8) -> DoctypeResult {
161	        loop {
162	            match self.phase {
163	                DoctypePhase::Start => {
164	                    if !is_xml_whitespace(byte) { return DoctypeResult::Bad; }
165	                    self.phase = DoctypePhase::Main;
166	                    return DoctypeResult::More;
167	                }
168	                DoctypePhase::Main => match byte {
169	                    b'"' | b'\'' => { self.quote = byte; self.phase = DoctypePhase::Quote; }
170	                    b'[' => {
171	                        if self.subset_closed { return DoctypeResult::Bad; }
172	                        self.phase = DoctypePhase::Subset;
173	                    }
174	                    b'>' => return DoctypeResult::Done,
175	                    b'<' => return DoctypeResult::Bad,
176	                    _ => {}
177	                },
178	                DoctypePhase::Quote => if byte == self.quote { self.phase = DoctypePhase::Main; },
179	                DoctypePhase::Subset => match byte {
180	                    b'"' | b'\'' => { self.quote = byte; self.phase = DoctypePhase::SubsetQuote; }
181	                    b'<' => self.phase = DoctypePhase::Lt,
182	                    b']' => { self.subset_closed = true; self.phase = DoctypePhase::Main; }
183	                    _ => {}
184	                },
185	                DoctypePhase::SubsetQuote => if byte == self.quote { self.phase = DoctypePhase::Subset; },
186	                DoctypePhase::Lt => match byte {
187	                    b'!' => { self.phase = DoctypePhase::Bang; return DoctypeResult::More; }
188	                    b'?' => { self.run = 0; self.phase = DoctypePhase::Pi; return DoctypeResult::More; }
189	                    _ => { self.phase = DoctypePhase::Subset; continue; }
190	                },
191	                DoctypePhase::Bang => if byte == b'-' { self.phase = DoctypePhase::BangDash; return DoctypeResult::More; } else { self.phase = DoctypePhase::Subset; continue; },
192	                DoctypePhase::BangDash => if byte == b'-' { self.run = 0; self.phase = DoctypePhase::Comment; return DoctypeResult::More; } else { self.phase = DoctypePhase::Subset; continue; },
193	                DoctypePhase::Comment => {
194	                    if byte == b'-' { self.run = self.run.saturating_add(1).min(2); }
195	                    else if byte == b'>' && self.run >= 2 { self.phase = DoctypePhase::Subset; }
196	                    else { self.run = 0; }
197	                }
198	                DoctypePhase::Pi => {
199	                    if byte == b'>' && self.run == 1 { self.phase = DoctypePhase::Subset; }
200	                    else { self.run = u8::from(byte == b'?'); }
201	                }
202	            }
203	            return DoctypeResult::More;
204	        }
205	    }
206	}
