209	pub struct XmlReader<'a> {
210	    source: &'a [u8],
211	    bytes_read: usize,
212	    token_start: usize,
213	    name_offset: usize,
214	    name_length: usize,
215	    attribute_count: usize,
216	    probe_position: usize,
217	    mode: Mode,
218	    probe: Probe,
219	    closing: bool,
220	    name_complete: bool,
221	    in_quote: bool,
222	    pending_slash: bool,
223	    self_closing: bool,
224	    quote: u8,
225	    complete: bool,
226	    element_seen: bool,
227	    doctype_seen: bool,
228	    doctype: DoctypeState,
229	    diagnostic: Diagnostic,
230	}
231	
232	impl<'a> XmlReader<'a> {
233	    /// Starts a reader borrowing `source` until this reader is dropped.
234	    pub fn new(source: &'a [u8]) -> Result<Self, ReaderStatus> {
235	        if source.len() > MAX_READER_SOURCE_BYTES { return Err(ReaderStatus::Limit); }
236	        Ok(Self {
237	            source, bytes_read: 0, token_start: 0, name_offset: 0, name_length: 0,
238	            attribute_count: 0, probe_position: 0, mode: Mode::Text, probe: Probe::None,
239	            closing: false, name_complete: false, in_quote: false, pending_slash: false,
240	            self_closing: false, quote: 0, complete: false, element_seen: false,
241	            doctype_seen: false, doctype: DoctypeState::default(), diagnostic: Diagnostic::clear(),
242	        })
243	    }
244	
245	    /// Advances by at most `byte_budget` bytes, capped at 64 KiB, and emits
246	    /// complete lexical tags. Returning false from the callback is an error.
247	    pub fn step<F>(&mut self, byte_budget: usize, mut on_tag: F) -> ReaderStatus
248	    where F: FnMut(ReaderTag) -> bool {
249	        if byte_budget == 0 { return ReaderStatus::Invalid; }
250	        if self.diagnostic.category != XmlError::None { return ReaderStatus::Malformed; }
251	        if self.complete { return ReaderStatus::Complete; }
252	        let budget = byte_budget.min(MAX_READER_STEP_BYTES);
253	        let end = self.bytes_read.saturating_add(budget).min(self.source.len());
254	        while self.bytes_read < end && self.diagnostic.category == XmlError::None {
255	            let at = self.bytes_read;
256	            let byte = self.source[at];
257	            match self.mode {
258	                Mode::Text => if byte == b'<' {
259	                    self.mode = Mode::Probe;
260	                    self.token_start = at;
261	                    self.probe = Probe::None;
262	                    self.probe_position = 0;
263	                },
264	                Mode::Probe => self.scan_probe(byte, at),
265	                Mode::Tag => {
266	                    if !self.name_complete {
267	                        if is_reader_name_byte(byte) {
268	                            if self.name_length == MAX_READER_NAME_BYTES { self.fail(XmlError::InvalidName, self.name_offset); }
269	                            else { self.name_length += 1; }
270	                            self.bytes_read += 1;
271	                            continue;
272	                        }
273	                        if self.name_length == 0 { self.fail(XmlError::InvalidName, self.name_offset); }
274	                        else { self.name_complete = true; }
275	                    }
276	                    if self.in_quote {
277	                        if byte == self.quote { self.in_quote = false; }
278	                    } else if byte == b'\'' || byte == b'"' {
279	                        self.in_quote = true;
280	                        self.quote = byte;
281	                        self.attribute_count = self.attribute_count.saturating_add(1);
282	                    } else if byte == b'/' { self.pending_slash = true; }
283	                    else if byte == b'>' {
284	                        self.self_closing = self.pending_slash;
285	                        if !self.emit_tag(at + 1, &mut on_tag) { break; }
286	                    } else { self.pending_slash = false; }
287	                }
288	                Mode::Comment if byte == b'>' && at >= 2 && &self.source[at - 2..at] == b"--" => self.mode = Mode::Text,
289	                Mode::Cdata if byte == b'>' && at >= 2 && &self.source[at - 2..at] == b"]]" => self.mode = Mode::Text,
290	                Mode::Doctype => match self.doctype.step(byte) {
291	                    DoctypeResult::Bad => self.fail(XmlError::MalformedSyntax, at),
292	                    DoctypeResult::Done => self.mode = Mode::Text,
293	                    DoctypeResult::More => {}
294	                },
295	                Mode::Pi if byte == b'>' && at > 0 && self.source[at - 1] == b'?' => self.mode = Mode::Text,
296	                _ => {}
297	            }
298	            self.bytes_read += 1;
299	        }
300	        if self.diagnostic.category != XmlError::None { return ReaderStatus::Malformed; }
301	        if self.bytes_read == self.source.len() {
302	            if self.mode != Mode::Text { self.fail(XmlError::IncompleteDocument, self.source.len()); }
303	            else { self.complete = true; }
304	        }
305	        if self.diagnostic.category == XmlError::None {
306	            if self.complete { ReaderStatus::Complete } else { ReaderStatus::Ok }
307	        } else { ReaderStatus::Malformed }
308	    }
309	
310	    pub fn progress(&self) -> ReaderProgress {
311	        ReaderProgress { bytes_read: self.bytes_read, source_bytes: self.source.len(), diagnostic: self.diagnostic, complete: self.complete }
312	    }
313	
314	    fn scan_probe(&mut self, byte: u8, at: usize) {
315	        if self.probe_position == 0 {
316	            if byte == b'?' { self.mode = Mode::Pi; }
317	            else if byte == b'/' {
318	                self.begin_tag(true, at + 1);
319	            } else if byte == b'!' { self.probe_position = 1; }
320	            else if is_reader_name_byte(byte) {
321	                self.begin_tag(false, at);
322	                self.name_length = 1;
323	            } else { self.fail(XmlError::InvalidName, at); }
324	        } else if self.probe == Probe::None {
325	            if byte == b'-' { self.probe = Probe::Comment; self.probe_position = 1; }
326	            else if byte == b'[' { self.probe = Probe::Cdata; self.probe_position = 1; }
327	            else if byte == b'D' && !self.doctype_seen && !self.element_seen {
328	                self.probe = Probe::Doctype;
329	                self.probe_position = 1;
330	            } else { self.fail(XmlError::UnsupportedDtd, self.token_start); }
331	        } else if self.probe == Probe::Comment {
332	            if byte != b'-' { self.fail(XmlError::MalformedSyntax, self.token_start); }
333	            else { self.mode = Mode::Comment; }
334	        } else if self.probe == Probe::Doctype {
335	            const TAIL: &[u8] = b"OCTYPE";
336	            let index = self.probe_position - 1;
337	            if TAIL.get(index).copied() != Some(byte) { self.fail(XmlError::UnsupportedDtd, self.token_start); }
338	            else if self.probe_position == TAIL.len() {
339	                self.mode = Mode::Doctype;
340	                self.doctype_seen = true;
341	                self.doctype = DoctypeState::default();
342	            } else { self.probe_position += 1; }
343	        } else {
344	            const TAIL: &[u8] = b"CDATA[";
345	            let index = self.probe_position - 1;
346	            if index >= TAIL.len() || TAIL[index] != byte { self.fail(XmlError::MalformedSyntax, self.token_start); }
347	            else if self.probe_position == TAIL.len() { self.mode = Mode::Cdata; }
348	            else { self.probe_position += 1; }
349	        }
350	    }
351	
352	    fn begin_tag(&mut self, closing: bool, name_offset: usize) {
353	        self.mode = Mode::Tag;
354	        self.closing = closing;
355	        self.name_offset = name_offset;
356	        self.name_length = 0;
357	        self.attribute_count = 0;
358	        self.name_complete = false;
359	        self.pending_slash = false;
360	    }
361	
362	    fn emit_tag<F>(&mut self, end: usize, callback: &mut F) -> bool
363	    where F: FnMut(ReaderTag) -> bool {
364	        if self.name_length == 0 || self.name_length > MAX_READER_NAME_BYTES {
365	            self.fail(XmlError::InvalidName, self.name_offset);
366	            return false;
367	        }
368	        if !self.closing { self.element_seen = true; }
369	        let kind = if self.closing { TagKind::EndElement } else if self.self_closing { TagKind::EmptyElement } else { TagKind::StartElement };
370	        let tag = ReaderTag {
371	            kind,
372	            source: Span { start: self.token_start, end },
373	            name: Span { start: self.name_offset, end: self.name_offset + self.name_length },
374	            attribute_count: self.attribute_count,
375	        };
376	        if !callback(tag) {
377	            self.fail(XmlError::OutputExhausted, self.token_start);
378	            return false;
379	        }
380	        self.mode = Mode::Text;
381	        true
382	    }
383	
384	    fn fail(&mut self, category: XmlError, offset: usize) {
385	        if self.diagnostic.category == XmlError::None {
386	            self.diagnostic = Diagnostic { category, offset: offset.min(self.source.len()) };
387	        }
388	    }
389	}
390	
391	fn is_reader_name_byte(byte: u8) -> bool {
392	    byte.is_ascii_alphanumeric() || byte >= 0x80 || matches!(byte, b'_' | b'-' | b'.' | b':')
393	}
